import {pounds,GBP_PER_UNIT} from './manager-money.js';
import {escapeHtml as esc,clubBadge,metric} from './ui-kit.js';
import {selectSquad} from './europe-clubs.js';
export function renderClubPicker(packs,selected,query="",{modern=false,selection=null,competition=null}={}){
 const matches=packs.filter(p=>(p.club+' '+p.era).toLowerCase().includes(query.trim().toLowerCase())).length; const pack=packs.find(p=>p.id===selected)||packs[0],squad=selectSquad(pack),avg=Math.round(pack.players.reduce((n,p)=>n+p.rating,0)/pack.players.length);
 return `<div class="club-selection"><div class="club-catalog"><label for="club-catalog-search">Find your club & era</label><input type="search" id="club-catalog-search" placeholder="Search Barcelona, Arsenal, 2014…" autocomplete="off" value="${esc(query)}"><p class="stat-foot" id="club-catalog-count">${matches} matching snapshots · authored game ratings</p><div class="club-card-grid">${packs.map(p=>`<button class="club-era-card ${p.id===pack.id?'selected':''}" data-action="eu-${selection||(modern?'select-english':'select-pack')}" data-value="${p.id}" data-club-search="${esc((p.club+' '+p.era).toLowerCase())}" aria-pressed="${p.id===pack.id}" ${!(p.club+' '+p.era).toLowerCase().includes(query.trim().toLowerCase())?'hidden':''} style="--club:${p.color}">${clubBadge(p.club,p.color)}<span><strong>${esc(p.club)}</strong><small>${esc(p.era)} · ${p.players.length} players${p.domesticRank?` · ${p.country} #${p.domesticRank}`:''}</small></span><span class="club-choice-arrow">↗</span></button>`).join('')}</div><p id="club-catalog-empty" ${matches?'hidden':''}>No matching snapshots. Try a club name or a different year.</p></div><aside class="club-preview" style="--club:${pack.color}"><div class="club-preview-top">${clubBadge(pack.club,pack.color)}<span class="eyebrow">YOUR NEXT CHAPTER</span><h2>${esc(pack.club)}</h2><p>${esc(pack.era)} · ${competition||(modern?'English league sandbox':'Historic fantasy career')}</p></div><div class="studio-metrics">${metric('Squad profile',avg+' OVR')}${metric('Starting shape',squad.formation)}${modern?metric('Opening budget',pounds(pack.budget*GBP_PER_UNIT)):''}</div><h3>Players to build around</h3><div class="preview-players">${[...pack.players].sort((a,b)=>b.rating-a.rating).slice(0,5).map(p=>`<div><span>${esc(p.name)}<small>${p.role}</small></span><b>${p.rating}</b></div>`).join('')}</div><p class="stat-foot">${modern?'Imported player-pool snapshot. Authored game ratings and budgets; registration audit incomplete.':'Historic players in an original fantasy league. Real domestic careers remain locked.'}</p></aside></div><input type="hidden" id="career-pack" value="${pack.id}">`;
}
export function filterClubPicker(input){const q=input.value.trim().toLowerCase(),cards=[...document.querySelectorAll('[data-club-search]')];let count=0;for(const card of cards){card.hidden=!card.dataset.clubSearch.includes(q);if(!card.hidden)count++;}document.querySelector('#club-catalog-count').textContent=count+' matching snapshots · authored game ratings';document.querySelector('#club-catalog-empty').hidden=count>0;}
